def   reporter_node (state: State, config: RunnableConfig) :      # 准备报告输入     input_ = {          "messages" : [HumanMessage( f"# Research Requirements

## Task

 {current_plan.title} 

## Description

 {current_plan.thought} " )],          "locale" : state.get( "locale" ,  "en-US" ),     }           # 应用提示模板     invoke_messages = apply_prompt_template( "reporter" , input_, configurable)           # 调用 LLM 生成报告     response = get_llm_by_type(AGENT_LLM_MAP[ "reporter" ]).invoke(invoke_messages)           # 返回最终报告      return  { "final_report" : response.content}
